CREATE TYPE "Role" AS ENUM ('USER','SUPERVISOR','ADMIN');
CREATE TYPE "SuggestionStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TABLE "users" ("id" BIGINT NOT NULL,"username" TEXT,"firstName" TEXT NOT NULL,"lastName" TEXT,"role" "Role" NOT NULL DEFAULT 'USER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "courses" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"normalizedTitle" TEXT NOT NULL,"instructor" TEXT NOT NULL,"normalizedInstructor" TEXT NOT NULL,"semester" TEXT NOT NULL,"normalizedSemester" TEXT NOT NULL,"link" TEXT NOT NULL,"description" TEXT,"createdById" BIGINT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "courses_pkey" PRIMARY KEY ("id"));
CREATE TABLE "suggestions" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"normalizedTitle" TEXT NOT NULL,"instructor" TEXT NOT NULL,"normalizedInstructor" TEXT NOT NULL,"semester" TEXT NOT NULL,"normalizedSemester" TEXT NOT NULL,"link" TEXT NOT NULL,"description" TEXT,"status" "SuggestionStatus" NOT NULL DEFAULT 'PENDING',"rejectionReason" TEXT,"submittedById" BIGINT NOT NULL,"reviewedById" BIGINT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "suggestions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bot_sessions" ("key" TEXT NOT NULL,"value" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,"userId" BIGINT,CONSTRAINT "bot_sessions_pkey" PRIMARY KEY ("key"));
CREATE INDEX "courses_normalizedTitle_idx" ON "courses"("normalizedTitle"); CREATE INDEX "courses_normalizedInstructor_idx" ON "courses"("normalizedInstructor"); CREATE INDEX "courses_normalizedSemester_idx" ON "courses"("normalizedSemester"); CREATE INDEX "suggestions_status_idx" ON "suggestions"("status");
ALTER TABLE "courses" ADD CONSTRAINT "courses_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "suggestions" ADD CONSTRAINT "suggestions_submittedById_fkey" FOREIGN KEY ("submittedById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "suggestions" ADD CONSTRAINT "suggestions_reviewedById_fkey" FOREIGN KEY ("reviewedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "bot_sessions" ADD CONSTRAINT "bot_sessions_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
